282	 * is updated after every visited node; invariant: on return, *prev holds
283	 * the largest key seen so far in this walk, so each new node is compared
284	 * against the correct predecessor regardless of recursion depth. Returns
285	 * 0 if order holds throughout, nonzero on the first violation found. */
286	static int check_bst_order(const struct rb_node *n, const char **prev)
287	{
288	    if (n == NIL) {
289	        return 0;
290	    }
291	    if (check_bst_order(n->left, prev) != 0) {
292	        return -1;
293	    }
294	    if (*prev != NULL && strcmp(n->key, *prev) <= 0) {
295	        return -1;
296	    }
