308	{
309	    if (n == NIL) {
310	        return 0;
311	    }
312	    int left_bh = check_rb_shape(n->left, count);
313	    if (left_bh < 0) {
314	        return -1;
315	    }
316	    int right_bh = check_rb_shape(n->right, count);
317	    if (right_bh < 0) {
318	        return -1;
319	    }
320	    if (left_bh != right_bh) {
321	        return -1;
322	    }
323	    if (n->color == RED && (n->left->color != BLACK || n->right->color != BLACK)) {
324	        return -1;
