345	static struct rb_node *bst_search(const rbtree_t *t, const char *key,
346	                                   struct rb_node **out_parent)
347	{
348	    struct rb_node *parent = NIL;
349	    struct rb_node *n = t->root;
350	
351	    /* invariant: n is always a strict descendant of parent (or NIL, while
352	     * still at the root), so each iteration strictly descends the tree
353	     * and the loop terminates at a leaf. */
354	    while (n != NIL) {
355	        int cmp = strcmp(key, n->key);
356	        if (cmp == 0) {
357	            if (out_parent != NULL) {
358	                *out_parent = n->parent;
359	            }
360	            return n;
361	        }
362	        parent = n;
363	        n = (cmp < 0) ? n->left : n->right;
364	    }
365	
366	    if (out_parent != NULL) {
367	        *out_parent = parent;
368	    }
369	    return NIL;
370	}
