383	static struct rb_node *node_alloc(void)
384	{
385	    struct rb_node *n = malloc(sizeof *n);
386	    if (n == NULL) {
387	        return NULL;
388	    }
389	
390	    n->key = NULL;
391	    n->value = NULL;
392	    n->color = RED;
393	    n->left = NIL;
394	    n->right = NIL;
395	    n->parent = NIL;
396	
397	    return n;
398	}
