401	{
402	    free(n->key);
403	    if (t->value_free != NULL) {
404	        t->value_free(n->value);
405	    }
406	    free(n);
407	}
408	
409	static void free_subtree(rbtree_t *t, struct rb_node *n)
410	{
411	    /* invariant: each recursive call operates on a strictly smaller
412	     * subtree (one fewer node between n and the nearest NIL leaf), so
413	     * recursion terminates at NIL; depth is bounded by tree height. */
414	    if (n == NIL) {
415	        return;
416	    }
417	    free_subtree(t, n->left);
418	    free_subtree(t, n->right);
419	    node_destroy(t, n);
420	}
