1	/* White-box tests for insert_fixup. The public API (include/rbtree.h,
2	 * the graded contract) intentionally exposes no way to inspect node color
3	 * or tree shape, so this translation unit #includes rbtree.c directly to
4	 * reach struct rb_node, NIL, and enum color, and asserts on the three
5	 * classic red-black fixup cases by name:
6	 *   1. uncle red      -> recolor, no rotation
7	 *   2. triangle        -> rotate around the parent, then the grandparent
8	 *   3. line (straight) -> a single rotation around the grandparent
9	 * Each expected tree shape below was hand-derived by tracing the CLRS
10	 * RB-INSERT-FIXUP algorithm for the exact key sequence inserted. */
11	#include "../src/rbtree.c"
12	
13	#include <stdio.h>
14	
15	static int failures = 0;
16	
17	#define CHECK(cond, msg) \
18	    do { \
19	        if (!(cond)) { \
20	            fprintf(stderr, "  FAIL: %s (%s:%d)\n", msg, __FILE__, __LINE__); \
21	            failures++; \
22	        } \
23	    } while (0)
24	
25	static struct rb_node *find_node(rbtree_t *t, const char *key)
26	{
27	    return bst_search(t, key, NULL);
28	}
29	
30	/* Builds a standalone node (key copy owned like a normal insert would),
31	 * bypassing rb_insert so tests can wire up an exact tree shape by hand and
32	 * exercise rotate_left/rotate_right directly, independent of insert_fixup. */
33	static struct rb_node *make_node(const char *key)
34	{
35	    struct rb_node *n = node_alloc();
