274	/* m(black) gets red children d and t; inserting b under d creates a
275	 * red-red conflict (b, d) with a red uncle (t) -> parent and uncle turn
276	 * black, grandparent (m, the root) turns red then back to black by the
277	 * end-of-function root fixup. No rotation, no shape change. */
278	static void test_uncle_red_recolors(void)
279	{
280	    printf("test_uncle_red_recolors\n");
281	    rbtree_t *t = rb_create(NULL);
282	    int v = 0;
283	
284	    rb_insert(t, "m", &v);
285	    rb_insert(t, "d", &v);
286	    rb_insert(t, "t", &v);
287	    rb_insert(t, "b", &v);
288	
289	    struct rb_node *root = t->root;
290	    struct rb_node *d = find_node(t, "d");
291	    struct rb_node *tt = find_node(t, "t");
292	    struct rb_node *b = find_node(t, "b");
293	
294	    CHECK(strcmp(root->key, "m") == 0, "recolor case must not change the root key");
295	    CHECK(root->color == BLACK, "root must stay black");
296	    CHECK(d->color == BLACK, "parent must be recolored black");
297	    CHECK(tt->color == BLACK, "uncle must be recolored black");
298	    CHECK(b->color == RED, "newly inserted node stays red");
299	    CHECK(d->parent == root, "recolor must not change d's position");
300	    CHECK(tt->parent == root, "recolor must not change t's position");
301	    CHECK(b->parent == d, "recolor must not change b's position");
302	
303	    rb_destroy(t);
304	}
