306	/* m(black) gets a red left child d (no uncle, uncle is NIL/black).
307	 * Inserting f (d < f < m) makes f a red right child of red left child d:
308	 * a triangle. fixup rotates left around d first, then right around m,
309	 * leaving f as the new (black) subtree root with d and m as red children. */
310	static void test_triangle_case_rotates_twice(void)
311	{
312	    printf("test_triangle_case_rotates_twice\n");
313	    rbtree_t *t = rb_create(NULL);
314	    int v = 0;
315	
316	    rb_insert(t, "m", &v);
317	    rb_insert(t, "d", &v);
318	    rb_insert(t, "f", &v);
319	
320	    struct rb_node *root = t->root;
321	
322	    CHECK(strcmp(root->key, "f") == 0, "triangle fixup should promote f to subtree root");
323	    CHECK(root->color == BLACK, "post-fixup root must be black");
324	    CHECK(strcmp(root->left->key, "d") == 0, "d should end up as f's left child");
325	    CHECK(strcmp(root->right->key, "m") == 0, "m should end up as f's right child");
326	    CHECK(root->left->color == RED, "d stays red after rotation");
327	    CHECK(root->right->color == RED, "m becomes red after rotation");
328	    CHECK(root->left->parent == root, "d's parent pointer must be fixed up to f");
329	    CHECK(root->right->parent == root, "m's parent pointer must be fixed up to f");
330	
331	    rb_destroy(t);
332	}
