386	/* Inserts a larger, unsorted key set and checks rb_validate after every
387	 * single insert, not just at the end -- this exercises whatever mix of
388	 * recolors and rotations each insert happens to trigger, organically, as
389	 * a general regression net for insert_fixup rather than one hand-picked
390	 * shape. */
391	static void test_validate_holds_after_every_insert(void)
392	{
393	    printf("test_validate_holds_after_every_insert\n");
394	    rbtree_t *t = rb_create(NULL);
395	    const char *keys[] = { "m", "d", "t", "b", "f", "p", "z", "a", "c", "e" };
396	    size_t n = sizeof(keys) / sizeof(keys[0]);
397	    int v = 0;
398	
399	    for (size_t i = 0; i < n; i++) {
400	        rb_insert(t, keys[i], &v);
401	        CHECK(rb_validate(t) == 0, "tree must remain a valid red-black tree after every insert");
402	    }
403	
404	    rb_destroy(t);
405	}
