407	/* ---- rb_validate: negative cases ----
408	 * Each test builds a small valid tree via rb_insert (sanity-checked with
409	 * rb_validate == 0), then corrupts exactly one invariant by hand and
410	 * checks that rb_validate rejects it. Corruptions are chosen to leave the
411	 * other invariants intact where possible, so each test isolates the one
412	 * check it names. */
413	
414	/* d is m's LEFT child but its key is mutated to "z" (> "m"): a pure BST
415	 * ordering violation. Colors/shape are untouched, so this isolates
416	 * check_bst_order specifically. */
417	static void test_validate_detects_bst_order_violation(void)
418	{
419	    printf("test_validate_detects_bst_order_violation\n");
420	    rbtree_t *t = rb_create(NULL);
421	    int v = 0;
422	
423	    rb_insert(t, "m", &v);
424	    rb_insert(t, "d", &v);
425	    rb_insert(t, "t", &v);
426	    CHECK(rb_validate(t) == 0, "sanity: tree must be valid before corrupting it");
427	
428	    struct rb_node *d = find_node(t, "d");
429	    free(d->key);
430	    d->key = copy_key("z"); /* "z" > "m", but still m's left child */
431	
432	    CHECK(rb_validate(t) != 0, "rb_validate must reject a left child whose key exceeds its ancestor");
433	
434	    rb_destroy(t);
435	}
436	
437	/* d is already red (single red child of black root m). Manually attaching
438	 * a second red node (e) as d's right child creates a real red-red
439	 * conflict. t->size is bumped to match so the node-count check stays
440	 * consistent, isolating the red-red violation. */
441	static void test_validate_detects_red_red_violation(void)
442	{
443	    printf("test_validate_detects_red_red_violation\n");
444	    rbtree_t *t = rb_create(NULL);
445	    int v = 0;
446	
447	    rb_insert(t, "m", &v);
448	    rb_insert(t, "d", &v);
449	    CHECK(rb_validate(t) == 0, "sanity: tree must be valid before corrupting it");
450	
451	    struct rb_node *d = find_node(t, "d");
452	    CHECK(is_red(d), "sanity: d must already be red for this to be a real red-red conflict");
453	
454	    struct rb_node *e = make_node("e"); /* "e" > "d": fits as d's right child in order */
455	    e->parent = d;
456	    e->color = RED;
457	    d->right = e;
458	    t->size++;
459	
460	    CHECK(rb_validate(t) != 0, "rb_validate must reject a red node with a red child");
461	
462	    rb_destroy(t);
463	}
464	
465	/* d starts red (m's only child, right child stays NIL). Forcing d black
466	 * makes the left subtree's black-height 1 while the right (NIL) subtree's
467	 * stays 0 -- a pure black-height mismatch, with order/red-red/count all
468	 * untouched. */
