#include "rbtree.h"

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

#define POOL_SIZE 200

/* Investigation-only stress test (not part of the graded suite): random
 * insert/delete over a fairly large pool, checking rb_validate() after
 * EVERY single op, to try to reach every delete_fixup case combination --
 * including case 1 (red sibling) immediately followed by case 3/4 in the
 * same loop iteration, which none of the hand-traced unit tests hit. */
int main(int argc, char **argv)
{
    long iterations = (argc > 1) ? strtol(argv[1], NULL, 10) : 2000000;
    unsigned seed = (argc > 2) ? (unsigned)strtol(argv[2], NULL, 10) : 12345;
    srand(seed);

    rbtree_t *t = rb_create(NULL);
    int present[POOL_SIZE] = {0};
    long value_store[POOL_SIZE];

    for (long iter = 0; iter < iterations; iter++) {
        int slot = rand() % POOL_SIZE;
        char key[16];
        snprintf(key, sizeof key, "key%d", slot);

        if (!present[slot]) {
            value_store[slot] = iter;
            if (rb_insert(t, key, (void *)(uintptr_t)(value_store[slot] + 1)) != 0) {
                fprintf(stderr, "insert failed unexpectedly at iter %ld\n", iter);
                return 1;
            }
            present[slot] = 1;
        } else {
            /* 50/50 between delete and overwrite-by-reinsert, to also mix
             * in insert_fixup activity between deletes. */
            if (rand() % 2 == 0) {
                if (rb_delete(t, key) != 0) {
                    fprintf(stderr, "delete failed unexpectedly at iter %ld key %s\n", iter, key);
                    return 1;
                }
                present[slot] = 0;
            } else {
                value_store[slot] = iter;
                rb_insert(t, key, (void *)(uintptr_t)(value_store[slot] + 1));
            }
        }

        if (rb_validate(t) != 0) {
            fprintf(stderr, "rb_validate FAILED at iter %ld after op on %s (seed %u)\n",
                    iter, key, seed);
            return 1;
        }

        size_t expected_size = 0;
        for (int i = 0; i < POOL_SIZE; i++) {
            if (present[i]) expected_size++;
        }
        if (rb_size(t) != expected_size) {
            fprintf(stderr, "size mismatch at iter %ld: expected %zu got %zu\n",
                    iter, expected_size, rb_size(t));
            return 1;
        }
    }

    rb_destroy(t);
    printf("stress: %ld iterations OK (seed %u)\n", iterations, seed);
    return 0;
}

